    sx, sy = sx_sy[0], sx_sy[1]
    ox_oy = get_pos(["opponent_position", "enemy_position", "opp_position", "opponent_pos"], None)

    env = observation.get("environment_name", "resource_collection")
    role = observation.get("self_role", observation.get("role", "pursuer"))

    w = observation.get("grid_width", observation.get("width", 0))
    h = observation.get("grid_height", observation.get("height", 0))

    if env == "pursuit_evasion":
        if role == "pursuer":
            if ox_oy is not None:
                return step_toward([sx, sy], ox_oy)
