            if targets:
                best = min((p for p in (pos_list(t) for t in targets) if p is not None),
                           key=lambda p: manhattan([sx, sy], p))
                return step_toward([sx, sy], best)
            return [0, 0]
        if ox_oy is None:
            ox_oy = [w // 2 if w else sx, h // 2 if h else sy]
        corners = [[0, 0], [0, max(0, h - 1)], [max(0, w - 1), 0], [max(0, w - 1), max(0, h - 1)]]
        best = None
        best_score = None
        for c in corners:
            score = manhattan(c, ox_oy)
            if best is None or score > best_score:
                best = c
                best_score = score
        return step_toward([sx, sy], best)

    if env == "territory_control":
        targets = []
        for key in ("unclaimed_cells", "opponent_territory", "frontier_cells", "target_cells"):
            vals = safe_items(observation.get(key))
            for t in vals:
                p = pos_list(t)
                if p is not None:
                    targets.append(p)
        if not targets:
            if ox_oy is not None:
                return step_away([sx, sy], ox_oy)
            return [0, 0]
        best = min(targets, key=lambda p: manhattan([sx, sy], p))
        if ox_oy is not None:
            cur = manhattan([sx, sy], ox_oy)
            cand = step_toward([sx, sy], best)
            nxt = [sx + cand[0], sy + cand[1]]
            if manhattan(nxt, ox_oy) < cur and len(targets) > 1:
                far = max(targets, key=lambda p: manhattan(p, ox_oy))
                return step_toward([sx, sy], far)
        return step_toward([sx, sy], best)

    resources = []
    for key in ("resources", "resource_positions", "food", "targets", "items"):
        vals = safe_items(observation.get(key))
        for t in vals:
            p = pos_list(t)
            if p is not None:
                resources.append(p)

    if resources:
        best = None
        best_score = None
        for r in resources:
            dself = manhattan([sx, sy], r)
            dop = manhattan(ox_oy, r) if ox_oy is not None else 999999
            score = dself * 2 - dop
            if best is None or score < best_score:
                best = r
                best_score = score
        return step_toward([sx, sy], best)

    if ox_oy is not None:
        return step_away([sx, sy], ox_oy)

    return [0, 0]

